12	struct DeactivateAccountScreenCoordinatorParameters {
13	    let clientProxy: ClientProxyProtocol
14	    let userIndicatorController: UserIndicatorControllerProtocol
15	}
16	
17	enum DeactivateAccountScreenCoordinatorAction {
18	    case accountDeactivated
19	}
20	
21	final class DeactivateAccountScreenCoordinator: CoordinatorProtocol {
22	    private let parameters: DeactivateAccountScreenCoordinatorParameters
23	    private let viewModel: DeactivateAccountScreenViewModelProtocol
24	    
25	    private var cancellables = Set<AnyCancellable>()
26	 
27	    private let actionsSubject: PassthroughSubject<DeactivateAccountScreenCoordinatorAction, Never> = .init()
28	    var actionsPublisher: AnyPublisher<DeactivateAccountScreenCoordinatorAction, Never> {
29	        actionsSubject.eraseToAnyPublisher()
30	    }
31	    
32	    init(parameters: DeactivateAccountScreenCoordinatorParameters) {
33	        self.parameters = parameters
34	        
35	        viewModel = DeactivateAccountScreenViewModel(clientProxy: parameters.clientProxy,
36	                                                     userIndicatorController: parameters.userIndicatorController)
37	    }
38	    
39	    func start() {
40	        viewModel.actionsPublisher.sink { [weak self] action in
41	            MXLog.info("Coordinator: received view model action: \(action)")
42	            
43	            guard let self else { return }
44	            switch action {
45	            case .accountDeactivated:
46	                actionsSubject.send(.accountDeactivated)
47	            }
48	        }
49	        .store(in: &cancellables)
50	    }
51	        
52	    func toPresentable() -> AnyView {
53	        AnyView(DeactivateAccountScreen(context: viewModel.context))
54	    }
55	}
